using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using System.Diagnostics;using UnityEditor;using UnityEngine;using UnityEngine.Rendering;using MashBoxSDK.AnimationStudio;using Object=UnityEngine.Object;
public static class StudioLoopSelectionValidation {
 const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public;static int checks,stage;static bool rotatedRingSetup;static StudioModelEditor ed;static StudioModelDocument doc;static SceneView view;static double next;static string error;static List<Vector2> points=new List<Vector2>();static string perf="";
 static void Check(bool b,string m){if(!b)throw new Exception(m);checks++;}static object Get(string n)=>typeof(StudioModelEditor).GetField(n,F).GetValue(ed);static void Set(string n,object v)=>typeof(StudioModelEditor).GetField(n,F).SetValue(ed,v);static object Call(string n,params object[] a)=>typeof(StudioModelEditor).GetMethods(F).Single(m=>m.Name==n&&m.GetParameters().Length==a.Length&&m.GetParameters().Select((p,i)=>a[i]==null||p.ParameterType.IsInstanceOfType(a[i])).All(v=>v)).Invoke(ed,a);
 static StudioModelDocument.Node Grid(int nx,int ny){var p=new Vector3[(nx+1)*(ny+1)];for(int y=0;y<=ny;y++)for(int x=0;x<=nx;x++)p[y*(nx+1)+x]=new Vector3(x-nx*.5f,y-ny*.5f,0);var t=new List<int>();var poly=new List<int>();for(int y=0;y<ny;y++)for(int x=0;x<nx;x++){int a=y*(nx+1)+x,b=a+nx+1;poly.AddRange(new[]{0,4,a,b,b+1,a+1});t.AddRange(new[]{a,b,b+1,a,b+1,a+1});}var m=new Mesh{indexFormat=p.Length>65535?IndexFormat.UInt32:IndexFormat.UInt16};m.vertices=p;m.triangles=t.ToArray();m.RecalculateNormals();return new StudioModelDocument.Node{mesh=m,cutPolygons=poly.ToArray(),cutTriangles=m.triangles};}
 static List<(int a,int b)> Edges(StudioMeshCuts c){var result=new List<(int,int)>();var seen=new HashSet<(int,int)>();foreach(var f in c.Faces)for(int i=0;i<f.Vertices.Count;i++){int a=f.Vertices[i],b=f.Vertices[(i+1)%f.Vertices.Count];if(seen.Add((Math.Min(a,b),Math.Max(a,b))))result.Add((a,b));}return result;}
 static StudioSelectionTopology Top(StudioModelDocument.Node n,out List<(int a,int b)> edges){var c=new StudioMeshCuts(n);edges=Edges(c);return new StudioSelectionTopology(c.Positions,c.Faces,edges,true);}
 static void Pure(){var n=Grid(8,6);var top=Top(n,out var edges);int E(int a,int b)=>edges.FindIndex(e=>e.a==a&&e.b==b||e.a==b&&e.b==a);int V(int x,int y)=>y*9+x;int seed=E(V(3,3),V(4,3)),previous=E(V(2,3),V(3,3));Check(top.SelectEdges(seed,previous).Count==8,"Horizontal loop crosses a regular grid");Check(top.SelectEdges(E(V(3,3),V(3,4)),E(V(3,2),V(3,3))).Count==6,"Perpendicular grid loop");Check(top.SelectEdges(E(V(3,2),V(3,3)),E(V(2,2),V(2,3))).Count==9,"Parallel vertical pair selects horizontal edge ring");Check(top.SelectEdges(E(V(3,3),V(4,3)),E(V(3,2),V(4,2))).Count==7,"Parallel horizontal pair selects perpendicular ring");Check(top.SelectEdges(E(V(0,0),V(1,0)),-1).Count==28,"Full boundary loop");Check(top.SelectVertices(V(2,3),V(3,3)).Count==9,"Vertex directional row");Check(top.SelectVertices(V(0,0),V(7,5)).Count==1,"Disconnected vertex pair must not jump");Check(top.SelectFaces(2+2*8,3+2*8).Count==8,"Face strip");Check(top.SelectFaces(0,0).Count==48,"Face connected hull");Check(top.SelectFaces(0,47).Count==1,"Nonadjacent face pair does not flood hull");Object.DestroyImmediate(n.mesh);
 var cube=StudioModelDocument.BuildPrimitive(PrimitiveType.Cube,out var poly);n=new StudioModelDocument.Node{mesh=cube,cutPolygons=poly,cutTriangles=cube.triangles};top=Top(n,out edges);var cut=new StudioMeshCuts(n);var face=cut.Faces[0].Vertices;int a0=E(face[0],face[1]),a1=E(face[1],face[2]);var result=top.SelectEdges(a1,a0);Check(result.Select(i=>top.RenderEdges[i]).Distinct().Count()==4,"Turning cube pair chooses face perimeter");Check(result.Count==8,"Cube UV/normal split aliases selected together");var unWelded=new StudioSelectionTopology(cut.Positions,cut.Faces,edges,false);Check(unWelded.SelectEdges(a1,a0).Count==4,"Unwelded traversal respects render seams");Check(top.SelectFaces(-1,0).Count==6,"Cube face hull");foreach(var f in cut.Faces)for(int side=0;side<4;side++){int first=E(f.Vertices[side],f.Vertices[(side+1)%4]),second=E(f.Vertices[(side+1)%4],f.Vertices[(side+2)%4]);var perimeter=top.SelectEdges(second,first);Check(perimeter.Select(i=>top.RenderEdges[i]).Distinct().Count()==4,"Directional cube perimeter on every side");Check(perimeter.Count==8,"Seam aliases on every cube side");int opposite=E(f.Vertices[(side+2)%4],f.Vertices[(side+3)%4]);var ring=top.SelectEdges(opposite,first);Check(ring.Select(i=>top.RenderEdges[i]).Distinct().Count()==4,"Opposite cube edges must select a ring");var direction=(cut.Positions[edges[first].b]-cut.Positions[edges[first].a]).normalized;Check(ring.All(i=>Vector3.Cross((cut.Positions[edges[i].b]-cut.Positions[edges[i].a]).normalized,direction).sqrMagnitude<1e-8f),"Cube edge-ring orientation differs from seed");}Object.DestroyImmediate(cube);
 var faces=new List<StudioMeshCuts.Face>{new StudioMeshCuts.Face{Vertices=new List<int>{0,1,2}},new StudioMeshCuts.Face{Vertices=new List<int>{1,0,3}},new StudioMeshCuts.Face{Vertices=new List<int>{0,1,4}}};var positions=new[]{Vector3.zero,Vector3.right,Vector3.up,Vector3.down,Vector3.forward};var render=new List<(int,int)>{(0,1),(1,2),(2,0),(0,3),(3,1),(1,4),(4,0)};var branched=new StudioSelectionTopology(positions,faces,render,false);Check(branched.EdgeLoop(0).Count==1,"Nonmanifold edge must not fan out");Check(branched.SelectFaces(-1,0).Count==1,"Hull must not cross nonmanifold seam");var ngon=new StudioSelectionTopology(positions,new List<StudioMeshCuts.Face>{new StudioMeshCuts.Face{Vertices=new List<int>{0,1,2,3,4}}},new List<(int,int)>{(0,1),(1,2),(2,3),(3,4),(4,0)},false);Check(ngon.EdgeLoop(0).Count==5,"Authored n-gon boundary retains no render diagonals");
 foreach(int size in new[]{32,128,256}){n=Grid(size,size);var clock=Stopwatch.StartNew();top=Top(n,out edges);clock.Stop();double build=clock.Elapsed.TotalMilliseconds;int row=size/2;int id=edges.FindIndex(e=>e.a==row*(size+1)+2&&e.b==row*(size+1)+3||e.b==row*(size+1)+2&&e.a==row*(size+1)+3);var samples=new double[100];for(int k=0;k<110;k++){clock.Restart();var loop=top.SelectEdges(id,-1);clock.Stop();Check(loop.Count==size,"Dense warm loop length");if(k>=10)samples[k-10]=clock.Elapsed.TotalMilliseconds;}Array.Sort(samples);var source=new StudioMeshCuts(n);var renderEdges=Edges(source);clock.Restart();var built=new StudioSelectionTopology(source.Positions,source.Faces,renderEdges,true);clock.Stop();double adjacency=clock.Elapsed.TotalMilliseconds;
 var part=new StudioRetopologyDocument.Part{vertices=source.Positions.ToList(),faces=source.Faces.Select(f=>new StudioRetopologyDocument.Face(f.Vertices.ToArray())).ToList()};var reference=typeof(StudioRetopologyEditor).GetMethod("ConnectedEdgeLoop",BindingFlags.Static|BindingFlags.NonPublic);var oldTimes=new double[5];for(int k=0;k<5;k++){clock.Restart();var old=(HashSet<(int,int)>)reference.Invoke(null,new object[]{part,(edges[id].a,edges[id].b)});clock.Stop();Check(old.Count==size,"Retopology reference differs on regular grid");oldTimes[k]=clock.Elapsed.TotalMilliseconds;}Array.Sort(oldTimes);
 perf+=$"grid={size}x{size} adjacency_only_ms={adjacency:F3} retopo_median_ms={oldTimes[2]:F3} vertices={n.mesh.vertexCount} capture_ms={build:F3} warm_median_ms={samples[50]:F4} p95_ms={samples[95]:F4}\n";Object.DestroyImmediate(n.mesh);}}
 public static void Run(){EditorApplication.delayCall+=()=>{try{Pure();doc=ScriptableObject.CreateInstance<StudioModelDocument>();doc.nodes.Add(Grid(8,4));var other=Grid(8,4);other.position=Vector3.right*30;doc.nodes.Add(other);ed=new StudioModelEditor(()=>view?.Repaint());ed.Load(doc);ed.SelectObject(0);ed.SetToolbarComponentMode(StudioModelEditor.ComponentMode.Edge);Set("tool",Tool.None);view=ScriptableObject.CreateInstance<SceneView>();typeof(SceneView).GetProperty("customScene",F).SetValue(view,ed.Scene);view.position=new Rect(100,100,1000,750);view.Show();view.LookAtDirect(Vector3.zero,Quaternion.identity,5);SceneView.duringSceneGui+=Scene;next=EditorApplication.timeSinceStartup+1;EditorApplication.update+=Tick;}catch(Exception e){Finish(e.ToString());}};}
 static void Scene(SceneView v){if(v!=view)return;try{points.Clear();var mode=ed.ToolbarComponentMode;Vector3 a=mode==StudioModelEditor.ComponentMode.Vertex?new Vector3(-2,0,0):mode==StudioModelEditor.ComponentMode.Edge?new Vector3(-1.5f,0,0):new Vector3(-1.5f,-.5f,0);points.Add(HandleUtility.WorldToGUIPoint(ed.Transforms[0].TransformPoint(a)));points.Add(HandleUtility.WorldToGUIPoint(ed.Transforms[0].TransformPoint(a+Vector3.right)));foreach(var p in new[]{new Vector3(-1.5f,-1,0),new Vector3(-1.5f,0,0),new Vector3(-2,-.5f,0),new Vector3(-1,-.5f,0)})points.Add(HandleUtility.WorldToGUIPoint(ed.Transforms[0].TransformPoint(p)));ed.SceneGUI(view,null);}catch(Exception e){error=e.ToString();}}
 static void Click(Vector2 p,int count,EventModifiers modifiers=EventModifiers.None){view.SendEvent(new Event{type=EventType.Layout});view.SendEvent(new Event{type=EventType.MouseDown,button=0,clickCount=count,mousePosition=p,modifiers=modifiers});view.SendEvent(new Event{type=EventType.MouseUp,button=0,clickCount=count,mousePosition=p,modifiers=modifiers});}
 static void Tick(){if(EditorApplication.timeSinceStartup<next)return;next=EditorApplication.timeSinceStartup+.25;try{if(error!=null)throw new Exception(error);if(stage>=3){if(!rotatedRingSetup){NativeRings();doc.nodes[0].rotation=Quaternion.Euler(90,0,0);ed.Transforms[0].rotation=doc.nodes[0].rotation;view.LookAtDirect(Vector3.zero,doc.nodes[0].rotation,5);rotatedRingSetup=true;view.Repaint();return;}NativeRings();Finish("PASS "+checks+" topology/native gesture/history/cache checks\n"+perf);return;}var mode=new[]{StudioModelEditor.ComponentMode.Vertex,StudioModelEditor.ComponentMode.Edge,StudioModelEditor.ComponentMode.Face}[stage];ed.SetToolbarComponentMode(mode);Set("tool",Tool.None);Call("ActivateComponentTarget",1,mode);ed.Components.Add(0);Call("ActivateComponentTarget",0,mode);ed.Components.Clear();view.SendEvent(new Event{type=EventType.Layout});view.SendEvent(new Event{type=EventType.Repaint});var p0=points[0];var p1=points[1];Click(p0,1);Check(ed.Components.Count==1,"First click "+mode);Click(p1,1);Check(ed.Components.Count==1,"First click on second component "+mode);Set("tool",Tool.Move);Click(p1,2);int expected=mode==StudioModelEditor.ComponentMode.Vertex?9:8;Check(ed.Components.Count==expected,"Directional double-click expansion "+mode+" got "+ed.Components.Count+" status="+Get("statusText"));Check(!(bool)Get("marquee")&&GUIUtility.hotControl==0,"Double-click releases selection capture");var state=Call("LoopState");var topology=state.GetType().GetField("topology",F).GetValue(state);Check(topology!=null,"Topology cache captured");var all=((Array)Call("CaptureComponentTargets")).Cast<object>().ToArray();var second=all.Single(v=>(int)v.GetType().GetField("node").GetValue(v)==1);Check(((int[])second.GetType().GetField("components").GetValue(second)).SequenceEqual(new[]{0}),"Expansion changed other mesh selection");UnityEditor.Undo.FlushUndoRecordObjects();ed.PerformWorkspaceHistory(false);Check(ed.Components.Count==1,"Expansion Undo retains prior seed");ed.PerformWorkspaceHistory(true);Check(ed.Components.Count==expected,"Expansion Redo");Set("tool",Tool.None);Click(p0,1);Click(p1,1);Click(p1,2);var warm=Call("LoopState");Check(ReferenceEquals(warm.GetType().GetField("topology",F).GetValue(warm),topology),"Selection-only clicks rebuilt adjacency");ed.Components.Add(0);Click(p1,2,EventModifiers.Shift);Check(ed.Components.Count==expected+1&&ed.Components.Contains(0),"Shift-double-click did not retain outside component");Click(p1,2,EventModifiers.Control);Check(ed.Components.SetEquals(new[]{0}),"Ctrl-double-click did not subtract loop");
 var beforeDirty=Call("LoopState");EditorUtility.SetDirty(ed.ActiveMesh);Check(!ReferenceEquals(beforeDirty,Call("LoopState")),"Mesh changes retained stale adjacency");
 stage++;view.Repaint();}catch(Exception e){Finish(e.ToString());}}
 static void NativeRings(){ed.SetToolbarComponentMode(StudioModelEditor.ComponentMode.Edge);Set("tool",Tool.None);view.SendEvent(new Event{type=EventType.Layout});view.SendEvent(new Event{type=EventType.Repaint});var p=points.ToArray();var positions=ed.ActiveMesh.vertices;for(int axis=0;axis<2;axis++){Click(p[2+axis*2],1);Click(p[3+axis*2],1);Set("tool",Tool.Move);Click(p[3+axis*2],2);Check(ed.Components.Count==(axis==0?5:9),"Native opposite-pair ring count on "+(rotatedRingSetup?"XZ":"XY")+" axis "+axis);var edges=(List<(int a,int b)>)Call("Edges");var expected=axis==0?Vector3.right:Vector3.up;Check(ed.Components.All(i=>Vector3.Cross((positions[edges[i].b]-positions[edges[i].a]).normalized,expected).sqrMagnitude<1e-8f),"Native ring chose the loop orientation");Set("tool",Tool.None);}}
 static void Finish(string r){EditorApplication.update-=Tick;SceneView.duringSceneGui-=Scene;File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../loop-selection-result.txt")),r);EditorApplication.delayCall+=()=>{try{if(view)view.Close();ed?.Dispose();}finally{EditorApplication.Exit(r.StartsWith("PASS")?0:1);}};}
}

